/// <summary>
/// Extension of Complete button control of Sales order details form (SalesTable)
/// </summary>
[ExtensionOf(formControlStr(SalesTable, Complete))]
final class METSalesTableFormCompleteButton_Extension
{
}

Method.Source:
    /// <summary>
    /// Click extension method to trigger the Sales order guide rule enforcement on completion of sales order
    /// </summary>
    void clicked()
    {
        next clicked();
        
        SalesTable salesTableLoc = this.formRun().dataSource(formDataSourceStr(SalesTable, SalesTable)).cursor();

        METSalesOrderGuideExecution::applyChecksToOrder(salesTableLoc.SalesId);
    }
